from dataclasses import dataclass
from datetime import datetime


@dataclass(frozen=True)
class Event:
    event_id: str
    date: str
    time: str
    category: str
    cents: int


def decode_event_batch(data, processed_ids):
    if not isinstance(data, str):
        raise TypeError("data must be a string")
    if not isinstance(processed_ids, set) or any(not isinstance(x, str) for x in processed_ids):
        raise TypeError("processed_ids must be a set of strings")

    parsed = []
    for raw_record in data.split(";"):
        if not raw_record.strip():
            continue
        fields = {}
        for part in raw_record.split("|"):
            if part.count("=") != 1:
                raise ValueError("each field must contain one equals sign")
            key, value = part.split("=", 1)
            if not key or not value or key in fields:
                raise ValueError("empty or duplicate field")
            fields[key] = value
        if set(fields) != {"id", "at", "cents", "category"}:
            raise ValueError("incorrect fields")
        try:
            moment = datetime.strptime(fields["at"], "%Y%m%dT%H%M%S")
        except ValueError as exc:
            raise ValueError("invalid timestamp") from exc
        raw_cents = fields["cents"]
        if not raw_cents.isascii() or not raw_cents.isdigit():
            raise ValueError("invalid cents")
        parsed.append((fields, moment, int(raw_cents)))

    updated = processed_ids
    events = []
    for fields, moment, cents in parsed:
        event_id = fields["id"]
        if event_id in updated:
            continue
        updated.add(event_id)
        events.append(Event(event_id, moment.strftime("%d.%m.%Y"), moment.strftime("%H:%M:%S"), fields["category"], cents))
    return events, updated

